import pytest


def test_invariant_no_discount_keeps_price():
    from shop.pricing import apply_discount
    assert apply_discount(100.0, 0.0) == pytest.approx(100.0), "0% off keeps price"


def test_invariant_ten_percent_off():
    from shop.pricing import apply_discount
    assert apply_discount(100.0, 10.0) == pytest.approx(90.0), "10% off 100 is 90"


def test_invariant_hundred_percent_free():
    from shop.pricing import apply_discount
    assert apply_discount(50.0, 100.0) == pytest.approx(0.0), "100% off is free"


def test_invariant_over_hundred_percent_free():
    from shop.pricing import apply_discount
    assert apply_discount(50.0, 150.0) == pytest.approx(0.0), "over 100% off stays zero"


def test_invariant_zero_price_stays_zero():
    from shop.pricing import apply_discount
    assert apply_discount(0.0, 10.0) == pytest.approx(0.0), "zero price stays zero"


def test_invariant_very_large_price():
    from shop.pricing import apply_discount
    assert apply_discount(1e12, 10.0) == pytest.approx(9e11), "large price discounts correctly"


def test_invariant_bulk_empty_is_zero():
    from shop.pricing import bulk_price
    assert bulk_price([], 10.0) == pytest.approx(0.0), "empty bulk totals zero"


def test_invariant_bulk_sums_discounted():
    from shop.pricing import bulk_price
    assert bulk_price([100.0, 50.0], 10.0) == pytest.approx(135.0), "bulk sums discounted prices"


def test_invariant_bulk_rounded_to_cents():
    from shop.pricing import bulk_price
    assert bulk_price([0.333, 0.333], 0.0) == pytest.approx(0.67), "bulk total rounded to cents"

