import pytest


class FakeRow(tuple):
    def __new__(cls, oid, customer, amount, created):
        return super().__new__(cls, (oid, customer, amount, created))

    def __getitem__(self, key):
        if isinstance(key, str):
            low = key.lower()
            mapping = {
                "id": 0,
                "order_id": 0,
                "oid": 0,
                "customer": 1,
                "customer_name": 1,
                "cust": 1,
                "name": 1,
                "customer_id": 1,
                "total": 2,
                "amount": 2,
                "price": 2,
                "sum": 2,
                "created_at": 3,
                "created": 3,
                "date": 3,
                "timestamp": 3,
                "time": 3,
            }
            if low in mapping:
                return super().__getitem__(mapping[low])
            raise KeyError(key)
        return super().__getitem__(key)

    def __getattr__(self, name):
        try:
            return self.__getitem__(name)
        except KeyError:
            raise AttributeError(name)

    def keys(self):
        return ["id", "customer", "total", "created_at"]

    def get(self, key, default=None):
        try:
            return self.__getitem__(key)
        except Exception:
            return default


class FakeCursor:
    def __init__(self, rows):
        self.rows = list(rows)
        self.lastsql = ""
        self.lastparams = ()

    def execute(self, sql, params=None):
        self.lastsql = sql if isinstance(sql, str) else str(sql)
        if params is None:
            self.lastparams = ()
        elif isinstance(params, dict):
            self.lastparams = tuple(params.values())
        elif isinstance(params, (list, tuple)):
            self.lastparams = tuple(params)
        else:
            self.lastparams = (params,)
        return self

    def fetchall(self):
        return self.filteredSorted()

    def fetchone(self):
        got = self.filteredSorted()
        return got[0] if got else None

    def fetchmany(self, n=None):
        got = self.filteredSorted()
        if n is None:
            return got
        return got[:n]

    def __iter__(self):
        return iter(self.filteredSorted())

    def filteredSorted(self):
        sqlup = self.lastsql.upper() if isinstance(self.lastsql, str) else ""
        rows = list(self.rows)
        known = set()
        for r in rows:
            try:
                known.add(r[1])
            except Exception:
                pass
        target = None
        for p in self.lastparams:
            if isinstance(p, str):
                target = p
                break
        if target is None:
            for k in known:
                if ("'" + k + "'") in self.lastsql or ('"' + k + '"') in self.lastsql:
                    target = k
                    break
        if "WHERE" in sqlup:
            if target is not None:
                rows = [r for r in rows if r[1] == target]
        if "ORDER BY" in sqlup:
            reverse = "DESC" in sqlup
            try:
                rows = sorted(rows, key=lambda r: r[0], reverse=reverse)
            except Exception:
                pass
        return rows


def getCustomer(row):
    for attr in ("customer", "customer_name", "cust", "name"):
        try:
            v = getattr(row, attr)
            if isinstance(v, str):
                return v
        except Exception:
            pass
    for key in ("customer", "customer_name", "cust", "name", "customer_id"):
        try:
            v = row[key]
            if isinstance(v, str):
                return v
        except Exception:
            pass
    try:
        v = row[1]
        if isinstance(v, str):
            return v
    except Exception:
        pass
    try:
        vals = list(row.values()) if hasattr(row, "values") else list(row)
        for v in vals:
            if isinstance(v, str):
                return v
    except Exception:
        pass
    return None


def getOrderKey(row):
    for key in ("id", "order_id", "oid"):
        try:
            v = row[key]
            if isinstance(v, (int, float, str)):
                return v
        except Exception:
            pass
    for attr in ("id", "order_id", "oid"):
        try:
            v = getattr(row, attr)
            if isinstance(v, (int, float, str)):
                return v
        except Exception:
            pass
    try:
        v = row[0]
        if isinstance(v, (int, float, str)):
            return v
    except Exception:
        pass
    for key in ("created_at", "created", "date", "timestamp", "time"):
        try:
            v = row[key]
            if isinstance(v, (int, float, str)):
                return v
        except Exception:
            pass
    return None


def rowBelongsTo(row, customer):
    c = getCustomer(row)
    if c is not None:
        return c == customer
    try:
        return customer in str(row)
    except Exception:
        return False


def test_invariant_order_total_empty():
    from shop.orders import order_total
    result = order_total([])
    assert result == pytest.approx(0), "empty list totals zero"


def test_invariant_order_total_single():
    from shop.orders import order_total
    result = order_total([(10.0, 2)])
    assert result == pytest.approx(20.0), "single line multiplies"


def test_invariant_order_total_zero_price():
    from shop.orders import order_total
    result = order_total([(0.0, 5)])
    assert result == pytest.approx(0.0), "zero price totals zero"


def test_invariant_order_total_large():
    from shop.orders import order_total
    result = order_total([(1e9, 2000000)])
    assert result == pytest.approx(2e15), "very large totals scale"


def test_invariant_order_total_negative_raises():
    from shop.orders import order_total
    with pytest.raises(ValueError):
        order_total([(5.0, -1)])
    assert True, "negative quantity raises"


def test_invariant_order_total_zero_quantity_raises():
    from shop.orders import order_total
    with pytest.raises(ValueError):
        order_total([(5.0, 0)])
    assert True, "zero quantity raises"


def test_invariant_find_orders_filters_customer():
    from shop.orders import find_orders
    cur = FakeCursor([
        FakeRow(1, "alice", 10.0, "2024-01-01"),
        FakeRow(2, "bob", 20.0, "2024-01-02"),
        FakeRow(3, "alice", 30.0, "2024-01-03"),
    ])
    result = find_orders(cur, "alice")
    assert all(rowBelongsTo(r, "alice") for r in result), "only customer orders"


def test_invariant_find_orders_newest_first():
    from shop.orders import find_orders
    cur = FakeCursor([
        FakeRow(1, "alice", 10.0, "2024-01-01"),
        FakeRow(2, "bob", 20.0, "2024-01-02"),
        FakeRow(3, "alice", 30.0, "2024-01-03"),
    ])
    result = find_orders(cur, "alice")
    ids = [getOrderKey(r) for r in result]
    assert ids == [3, 1], "newest first"


def test_invariant_find_orders_no_match_empty():
    from shop.orders import find_orders
    cur = FakeCursor([
        FakeRow(1, "alice", 10.0, "2024-01-01"),
        FakeRow(2, "bob", 20.0, "2024-01-02"),
    ])
    result = find_orders(cur, "zoe")
    assert result == [], "unknown customer empty"

