def test_invariant_empty_cart():
    from shop.cart import cart_count
    assert cart_count([]) == 0, "empty cart counts as 0"


def test_invariant_single_item():
    from shop.cart import cart_count
    assert cart_count([("apple", 2)]) == 2, "single line returns its quantity"


def test_invariant_multiple_items_summed():
    from shop.cart import cart_count
    assert cart_count([("a", 1), ("b", 3), ("c", 2)]) == 6, "quantities are summed"


def test_invariant_zero_quantity():
    from shop.cart import cart_count
    assert cart_count([("a", 0), ("b", 5)]) == 5, "zero quantity contributes 0"


def test_invariant_large_quantity():
    from shop.cart import cart_count
    assert cart_count([("a", 10**9), ("b", 10**9)]) == 2 * 10**9, "large sums exact"
